/** The model registry page, which **does not exist**.
 *
 * `apps/web/src/app/models/page.tsx` has never been in this repository —
 * `git log --all` finds no commit that added or removed it — while
 * `navigation.ts` has linked `/models` in the sidebar all along. The
 * backend half is built (`routers/models.py`, `model_registry.py`); the
 * page is not.
 *
 * **What that cost until now.** These three assertions read the file at
 * module scope, so the read threw during collection and vitest reported
 * one failed *suite* — taking the other **fourteen** tests in this file
 * down with it. They have never run. A dead link in the sidebar and a
 * silently disabled test file, from one missing page.
 *
 * The three claims are kept, in `MISSING_PAGES` below, where they are a
 * written-down requirement for whoever builds the page rather than a
 * crash. The nav test is what makes the gap visible now.
 */
const MISSING_PAGES: Record<string, string> = {
  "/models": [
    "The model registry page was specified and never built. The backend is done",
    "(routers/models.py, model_registry.py) and the sidebar already links here, so a",
    "user who clicks it gets a 404. When it is built it must: explain what a PPO model",
    "is (models.whatIsPpo), show an empty state rather than an error when nothing is",
    "uploaded (models.empty.title), and never render a storage location (no storage_key,",
    "no model_path) — that last one is the whole point of having a registry.",
  ].join(" "),
};

describe("every page the sidebar offers exists", () => {
  it("has no link that lands on a 404", () => {
    /* A dead sidebar entry is a promise the app does not keep, and
       nothing else in the suite looks for one. Listing the exception
       with its reason is what turns "it is missing" from something a
       reader discovers into something somebody wrote down. */
    const dead = NAV_SECTIONS.flatMap((section) => section.items)
      .map((item) => item.href)
      .filter((href) => href !== "/" && !href.startsWith("/auth/"))
      .filter((href) => !existsSync(join(APP, href.slice(1), "page.tsx")))
      .filter((href) => !(href in MISSING_PAGES));
    expect(dead).toEqual([]);
  });

  it("gives a reason for each page it knows is missing", () => {
    for (const [href, reason] of Object.entries(MISSING_PAGES)) {
      expect(reason.length, `${href}: the reason is too short to be one`).toBeGreaterThan(80);
      expect(existsSync(join(APP, href.slice(1), "page.tsx")), `${href} exists now`).toBe(false);
    }
  });
});

