      {stream.error ? (
        <div className="error-box">{t("simulate.stream", { message: stream.error })}</div>
      ) : null}

      {profiles.length === 0 ? (
        <div className="panel">
          <EmptyState
            icon="cpu"
            title={t("bench.empty.title")}
            body={t("bench.empty.body")}
            actionHref="/deployments"
            actionLabel={t("bench.empty.action")}
          />
        </div>
      ) : null}

